package com.pulsefit.subscriptionservice.controller; import com.pulsefit.subscriptionservice.entity.Plan; import com.pulsefit.subscriptionservice.repo.PlanRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/plans") public class PlanController {private final PlanRepository repo; public PlanController(PlanRepository r){repo=r;} @GetMapping public List<Plan> all(){return repo.findAll();} @PostMapping public ResponseEntity<Plan> add(@Valid @RequestBody Plan p){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(p));} @PutMapping("/{id}") public Plan update(@PathVariable Long id,@RequestBody Plan p){Plan x=repo.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found"));x.name=p.name;x.description=p.description;x.durationMonths=p.durationMonths;x.price=p.price;x.facilityAccess=p.facilityAccess;x.active=p.active;return repo.save(x);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Plan not found");repo.deleteById(id);return ResponseEntity.noContent().build();} }
